const OUT = process.argv[2];
const p = (text, ...src) => ({ t: "p", text, src });
const h = (text) => ({ t: "h", text });
const note = (text) => ({ t: "note", text });
const quote = (text, who, ...src) => ({ t: "quote", text, who, src });
const ex = (text, ...src) => ({ t: "example", text, src });
const facts = (...items) => ({ t: "facts", items: items.map(([value, label, ...src]) => ({ value, label, src })) });
const tl = (...items) => ({ t: "timeline", items: items.map(([when, text, ...src]) => ({ when, text, src })) });
const lesson = (title, text) => ({ t: "lesson", title, text });
const v = (name, years, outcome, idea, decision, howStarted, funding, whatHappened, lessonText, ...src) => ({
  t: "venture", name, years, outcome, idea, decision, howStarted, funding, whatHappened, lesson: lessonText, src,
});

